std::vector<int> A = {10, 20, 30, 50};
std::vector<int> B = {20, 30, 40};
std::vector<int> C; // Result container

// Computes A - B (elements in A but not in B)
std::set_difference(
    A.begin(), A.end(),
    B.begin(), B.end(),
    std::back_inserter(C)
);

// C is now {10, 50}

// Optional: Using a custom comparison (std::greater)
std::set_difference(
    A.rbegin(), A.rend(),
    B.rbegin(), B.rend(),
    std::back_inserter(C),
    std::greater<int>()
);
